package com.singtel.redemptionservice;import java.math.BigDecimal;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;class MoneyTest{@Test void halfUpRounding(){assertEquals(new BigDecimal("10.01"),Money.discount("PERCENTAGE",new BigDecimal("10"),new BigDecimal("100.05"),"SGD"));}@Test void cappedAtSpend(){assertEquals(new BigDecimal("20.00"),Money.discount("FIXED",new BigDecimal("40"),new BigDecimal("20"),"SGD"));}@Test void mismatchedCurrencyRejected(){assertThrows(com.singtel.platformcommon.DomainError.class,()->Money.discount("FIXED",BigDecimal.ONE,BigDecimal.TEN,"USD"));}}